import{z as s,x as m,o as l,c as A,q as n,j as i,D as o,d as t,s as B,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"OLMo 论文","description":"","frontmatter":{"title":"OLMo 论文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/olmo-paper.md","filePath":"llm/olmo-paper.md","lastUpdated":1791413859000}'),d={name:"llm/olmo-paper.md"};function p(h,a,T,D,L,u){const r=m("Mermaid");return l(),A("div",null,[a[2]||(a[2]=n('<h1 id="olmo-论文" tabindex="-1">OLMo 论文 <a class="header-anchor" href="#olmo-论文" aria-label="Permalink to &quot;OLMo 论文&quot;">​</a></h1><div class="epigraph"><p>与多数只开权重与推理代码的工作不同，我们把 OLMo 与训练数据、训练与评测代码一起发布，以便科学地研究语言模型。</p><footer>—— Groeneveld 等，OLMo: Accelerating the Science of Language Models，ACL 2024</footer></div><p>2024 年 Allen Institute for AI 把「开放」从开权重推进到可复现框架。ACL 长文给出的第一代 <strong>OLMo</strong> 是 1B 与 7B 稠密解码器，训在至少 <strong>2T</strong> token 上，数据是公开的 <a href="/llm/dolma-fineweb">Dolma</a>。后续 <a href="/llm/olmo2">OLMo 2</a> 才换成输出侧 RMSNorm、QK-Norm 与 Dolmino 退火。本篇按 arXiv:2402.00838 / ACL 2024 写第一代：架构表、Dolma 构成、在线评测与 Tülu 式适配，不把 2 代稳定性补丁写进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最强模型把数据、架构与训练日志收进专有接口之后，偏见、记忆、能力从哪条语料长出来，外部无法做因果分析。当时已有不同程度的开放：Mixtral 开权重、Llama 2 写适配说明、MPT 写数据分布但不给数据、Falcon 部分开数据、Pythia 与 BLOOM 把代码、检查点与数据摊得最开。OLMo 认为科学需要的是<strong>整条链</strong>——权重、中间检查点、日志、精确数据集、造数代码、评测器——并且质量要窄到当时 Llama 2 7B 这一档，而不是再做一个只能做通顺英语的 7B。</p><p>第二个问题是评测污染。公开数据上做困惑度，若不显式对评测集去污，会系统性低估困惑度。OLMo-7B 被写成当时最大的、为困惑度评测做过段落级去污的模型之一。</p><p><span class="marginnote">常见误区：以为评测污染只是「背过答案」。更常见的是背过整段文本——模型在预训练语料里见过评测集的段落，困惑度被系统性低估、选择题靠记忆答对。去污要做段落级 n-gram 匹配，文档级查重挡不住这种泄漏。</span></p><h3 id="_7b-四变体-不是一个检查点" tabindex="-1">7B 四变体，不是一个检查点 <a class="header-anchor" href="#_7b-四变体-不是一个检查点" aria-label="Permalink to &quot;7B 四变体，不是一个检查点&quot;">​</a></h3><p>报告交付：7B 四个变体（不同架构细节、优化器、训练硬件）加一个 1B，全部至少 2T token；Hugging Face 上数百个中间修订。7B 主评估点训到 <strong>2.46T</strong> Dolma，再在 Dolma 上 1000 步把学习率线性收到 0，以抬困惑度与下游。优化器一律 AdamW，\\(\\beta=(0.9,0.95)\\)，\\(\\epsilon=10^{-5}\\)。表：1B 为 16 层、\\(d=2048\\)、16 头、峰值学习率 \\(4\\times 10^{-4}\\)、预热 2000 步、绑嵌入、batch 约 4M token；7B 为 32 层、\\(d=4096\\)、32 头、2.46T、\\(3\\times 10^{-4}\\)、预热 5000、不绑嵌入。序列长度 <strong>2048</strong>。词表改自 GPT-NeoX-20B BPE，加 PII 掩码符，<strong>50280</strong>，嵌入矩阵垫到 50304 以对齐 128。</p><p><span class="marginnote">HTML 表有一处把 7B 隐宽印成 4086，实现与后续卡片均为 4096。写配置用 4096。不要把 2048 窗口口头升级成 OLMo 2 的 4096。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>相对「原版」Transformer 的改动是当时开源 7B 的常规包，而不是新核：去掉全部 bias；用<strong>非参数 LayerNorm</strong>（无仿射），报告认为这比参数 LN 和 RMSNorm 更稳也更快；<a href="/llm/swiglu">SwiGLU</a>，隐宽约 \\(8d/3\\) 再垫到 128 的倍数（7B 为 11008，门控输入因此是 22016）；RoPE。超参按硬件吞吐与防损失尖峰来选，并用每 1000 步（约 4B token）的在线下游评测做消融。</p><h3 id="dolma-按源分开的-2-7t" tabindex="-1">Dolma：按源分开的 2.7T <a class="header-anchor" href="#dolma-按源分开的-2-7t" aria-label="Permalink to &quot;Dolma：按源分开的 2.7T&quot;">​</a></h3><p>Dolma 管线：语言过滤、质量过滤、内容过滤、去重、多源混合、分词。报告 Table 2（GPT-NeoX 计）：Common Crawl 网页约 2.18T token，GitHub 代码约 342B，Reddit 约 80B，Semantic Scholar 约 57B，Gutenberg 约 5.2B，Wikipedia 约 3.7B，合计约 <strong>2.67T token</strong> / 4.37B 文档。各源在清洗与最终发布里保持分开，便于做「去掉某一源会怎样」。配套开源造数工具与 WIMBD 分析。适配走 Open Instruct / <a href="/llm/tulu">Tülu</a>：先指令 SFT，再 DPO。评测：Catwalk 做下游，Paloma 做 585 个域的困惑度；核心零样本套件对齐 Llama 2 文里的常识推理八任务。</p><p><span class="marginnote">数字实例：Dolma 约 2.67T token 里 Common Crawl 占约 2.18T——超过八成；GitHub 342B、Reddit 80B，而 Wikipedia 只有 3.7B。「万亿语料」的主食其实是网页，高质量策展源只是配菜，这正是「去掉某一源会怎样」消融有意义的原因。</span></p>',15)),(l(),i(E,null,{default:o(()=>[B(r,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22CC%20%2F%20GitHub%20%2F%20Reddit%20%2F%20%E8%AE%BA%E6%96%87%20%2F%20%E4%B9%A6%20%2F%20Wiki%22%5D%20--%3E%20DOL%5B%22Dolma%20%E8%BF%87%E6%BB%A4%E5%8E%BB%E9%87%8D%22%5D%0A%20%20DOL%20--%3E%20TOK%5B%22GPT-NeoX%20%E5%BC%8F%20BPE%2050k%22%5D%0A%20%20TOK%20--%3E%20TR%5B%22AdamW%20%E8%AE%AD%201B%20%2F%207B%20%E2%89%A52T%22%5D%0A%20%20TR%20--%3E%20CKPT%5B%22%E9%80%90%E6%AD%A5%E6%A3%80%E6%9F%A5%E7%82%B9%20%2B%20%E6%97%A5%E5%BF%97%22%5D%0A%20%20CKPT%20--%3E%20CAT%5B%22Catwalk%20%E4%B8%8B%E6%B8%B8%22%5D%0A%20%20CKPT%20--%3E%20PAL%5B%22Paloma%20%E5%8E%BB%E6%B1%A1%E5%9B%B0%E6%83%91%E5%BA%A6%22%5D%0A%20%20CKPT%20--%3E%20TULU%5B%22T%C3%BClu%20SFT%20%2B%20DPO%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"「真正开放」的机制不是多一个激活函数，而是让外部能问：MMLU 这一分是 Common Crawl 过滤、是 2.46T 之后的 1000 步退火，还是某一硬件变体的优化器。四份 7B 变体把架构 / 优化器 / 硬件拆开，避免把一次成功跑当成唯一配方。非参数 LN 去掉仿射，减少再引入一组易炸的增益；无 bias 是当时防尖峰的社区共识。SwiGLU 与 RoPE 则是跟 Llama / PaLM 对齐，降低「因为激活函数不同而无法对照」的噪声。",-1)),a[5]||(a[5]=e("p",null,"在线评测每 4B token 给一次下游信号，使数据混合与学习率可以在训练中途改，而不是训完才发现常识任务不动。Paloma 去污把「在训练里见过评测段落」从困惑度优势里拿掉，这样和 Pythia、RPJ-INCITE 等比的是拟合新域的能力。中间检查点让「能力何时出现」变成可画的曲线，而不只是最终一个点。",-1)),(l(),i(E,null,{default:o(()=>[B(r,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCORE%5B%22%E8%A7%82%E6%B5%8B%E5%88%B0%E6%9F%90%E4%B8%AA%E4%B8%8B%E6%B8%B8%E5%88%86%E6%95%B0%22%5D%20--%3E%20Q%7B%22%E8%B4%A1%E7%8C%AE%E6%9D%A5%E8%87%AA%E5%93%AA%E4%B8%AA%E6%97%8B%E9%92%AE%3F%22%7D%0A%20%20Q%20--%3E%20MIX%5B%22%E6%95%B0%E6%8D%AE%E6%B7%B7%E5%90%88%3A%20%E5%8E%BB%E6%8E%89%E6%9F%90%E6%BA%90%E9%87%8D%E8%AE%AD%E5%AF%B9%E7%85%A7%22%5D%0A%20%20Q%20--%3E%20ANNEAL%5B%222.46T%20%E5%90%8E%E7%9A%84%201000%20%E6%AD%A5%E9%80%80%E7%81%AB%22%5D%0A%20%20Q%20--%3E%20VAR%5B%22%E6%9E%B6%E6%9E%84%20%2F%20%E4%BC%98%E5%8C%96%E5%99%A8%20%2F%20%E7%A1%AC%E4%BB%B6%E5%9B%9B%E5%8F%98%E4%BD%93%22%5D%0A%20%20MIX%20--%3E%20EV%5B%22%E6%AF%8F%E6%9D%A1%E5%BD%92%E5%9B%A0%E9%83%BD%E6%9C%89%E5%85%AC%E5%BC%80%E8%AF%81%E6%8D%AE%E9%93%BE%22%5D%0A%20%20ANNEAL%20--%3E%20EV%0A%20%20VAR%20--%3E%20EV%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">直觉类比：在线评测像开车时的仪表盘——每 4B token 看一眼常识任务读数，发现不对可在中途改数据混合或学习率；不开仪表盘的训练是蒙眼开到终点才发现走错路，而那时几百万美元的算力已经花完。</span></p><p><span class="marginnote">代码与权重 Apache 2.0。Dolma 各源许可证并不自动等于 Apache：混合里若有更严条款，下游商用要按成分读。报告自己把框架许可写成 Apache，数据要另查 Dolma 文档。</span></p><h3 id="和-pythia、bloom、只开权重的-7b" tabindex="-1">和 Pythia、BLOOM、只开权重的 7B <a class="header-anchor" href="#和-pythia、bloom、只开权重的-7b" aria-label="Permalink to &quot;和 Pythia、BLOOM、只开权重的 7B&quot;">​</a></h3><p>Pythia 与 BLOOM 已经把透明度做到很高，但 2024 年初的英语学业 / 常识分与 Llama 2 7B 仍有可见缺口。OLMo 的主张是把缺口收窄，同时把数据提到万亿级可审计。Llama 2 / Mistral 仍可能在若干榜领先，它们不开 Dolma 原盘。不要把第一代 OLMo 写成已经打赢 Llama 3；那是 2 代 Pareto 叙事。多语不是这一代目标：Dolma 以英语为主，Reddit / 论文 / 维基都偏英。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>2048 不是长上下文产品。7B 不绑嵌入、1B 绑嵌入，加载时形状不同。词表 50280 与垫到 50304 的嵌入必须一起配，否则最后若干行是未训练填充。在线八任务偏常识补全，对代码与数学信号弱——这解释了为何后来 1.7 与 OLMo 2 要改数据与课程。Tülu 适配证明底座能聊，不等于附赠一个生产助手：偏好数据是蒸馏加人类的混合，安全策略要另做。</p><p>不要把 OLMoE 或 32B 写进 2024 这篇。不要给第一代编 QK-Norm。硬件变体若在论文表外，以 Hugging Face revision 名为准，不要合并成「官方唯一 7B」。Paloma 的 585 域是分层抽样，不是「互联网的均匀切片」：在 nytimes.com 上低困惑度，不蕴含在 r/depression 上同样拟合。读中间检查点时要用同一套 Catwalk 任务与 shot 设定，换 Eleuther harness 默认项会把「何时出现」的曲线画歪。1B 绑嵌入、7B 不绑，是吞吐与参数预算的选择，不是「小模型必须绑」。</p><p><span class="marginnote">正式出处：Groeneveld 等，<em>OLMo: Accelerating the Science of Language Models</em>，ACL 2024，预印本 arXiv:2402.00838。Dolma 是 Soldaini 等独立报告。OLMo 1.7–7B 是 2024 年中博客迭代（Dolma 1.7、两阶段、4K），不要与 ACL 论文的 2048 / Dolma 1.5 混成一张规格表。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>第一代 OLMo 是 Ai2 的全开放稠密模型：1B 与 7B（四变体），Dolma 上至少 2T，7B 评估点 2.46T。</li><li>架构为无 bias、非参数 LayerNorm、SwiGLU、RoPE、GPT-NeoX 式 50k 词表，序列 2048。</li><li>开放覆盖数据、造数代码、中间检查点、日志、Catwalk / Paloma 与 Tülu 适配。</li><li>设计目标是可科学复现并逼近当时 Llama 2 7B，而不是新注意力。</li><li>出处：Groeneveld 等，ACL 2024 / arXiv:2402.00838。</li></ul>',10))])}const g=s(d,[["render",p]]);export{P as __pageData,g as default};
